const esc = value => String(value).replace(/[&<>"']/g, char => ({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&apos;"}[char]));
const outline = `stroke="${PALETTE.ink}" stroke-width="5" stroke-linecap="round" stroke-linejoin="round"`;
const highlight = '<path d="M47 42c10-12 24-14 35-9" fill="none" stroke="#fff" stroke-width="6" stroke-linecap="round" opacity=".45"/>';

function objectShell(body, accent) {
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 160 160" role="img">${body}</svg>`;
}

function face(x=80,y=72) { return `<circle cx="${x-12}" cy="${y}" r="3.5" fill="${PALETTE.inkDark}"/><circle cx="${x+12}" cy="${y}" r="3.5" fill="${PALETTE.inkDark}"/><path d="M${x-7} ${y+13}q7 7 14 0" fill="none" stroke="${PALETTE.inkDark}" stroke-width="3.5" stroke-linecap="round"/>`; }

function animalArt(spec) {
  const c=spec.color, id=spec.id;
  if(id==="hamster") return objectShell(`<circle cx="80" cy="84" r="46" fill="${c}" ${outline}/><circle cx="48" cy="49" r="17" fill="${c}" ${outline}/><circle cx="112" cy="49" r="17" fill="${c}" ${outline}/><ellipse cx="80" cy="93" rx="29" ry="25" fill="#f5d7ad"/><circle cx="53" cy="91" r="10" fill="#ef9e9e" opacity=".65"/><circle cx="107" cy="91" r="10" fill="#ef9e9e" opacity=".65"/>${face(80,78)}<path d="M72 99h16M80 99v12" stroke="${PALETTE.inkDark}" stroke-width="3"/>`,c);
  if(id==="parrot") return objectShell(`<path d="M52 103q-18-50 17-76 35-26 59 9 18 26-7 53-18 20-13 45H71q6-17-19-31z" fill="${c}" ${outline}/><path d="M104 45q36-3 42 16-20 19-43 5" fill="${PALETTE.yellow}" ${outline}/><path d="M68 62q-22 31 7 52 37-7 41-45-22 14-48-7z" fill="#62b9df" ${outline}/><path d="m72 112-9 34M94 111l8 35" ${outline}/><circle cx="102" cy="42" r="5" fill="${PALETTE.inkDark}"/>`,c);
  if(id==="mouse") return objectShell(`<circle cx="49" cy="52" r="24" fill="${c}" ${outline}/><circle cx="111" cy="52" r="24" fill="${c}" ${outline}/><ellipse cx="80" cy="87" rx="48" ry="42" fill="${c}" ${outline}/><path d="m80 91 17 8-17 10-17-10z" fill="#ef8fb8" ${outline}/><circle cx="65" cy="79" r="4"/><circle cx="95" cy="79" r="4"/><path d="M48 99H15M52 110H20M112 99h33M108 110h32" stroke="${PALETTE.ink}" stroke-width="3"/>`,c);
  if(id==="monkey") return objectShell(`<circle cx="39" cy="78" r="22" fill="${c}" ${outline}/><circle cx="121" cy="78" r="22" fill="${c}" ${outline}/><circle cx="80" cy="78" r="48" fill="${c}" ${outline}/><path d="M80 49q-31 0-33 35-2 30 33 42 35-12 33-42-2-35-33-35z" fill="#e4b98b" ${outline}/>${face(80,76)}<ellipse cx="80" cy="100" rx="17" ry="11" fill="#d49a73"/>`,c);
  if(id==="gorilla") return objectShell(`<path d="M33 129q-15-58 16-87 31-29 62 0 31 29 16 87z" fill="${c}" ${outline}/><circle cx="80" cy="61" r="39" fill="${c}" ${outline}/><path d="M80 55q-26 0-27 28-1 25 27 34 28-9 27-34-1-28-27-28z" fill="#a8a3ac" ${outline}/>${face(80,70)}<path d="M38 84 17 132M122 84l21 48" ${outline}/>`,c);
  if(id==="horse") return objectShell(`<path d="M45 120V61q0-38 35-42 36-4 52 24l-14 27-23-5v55z" fill="${c}" ${outline}/><path d="M48 61Q25 84 36 123M61 26q-28 15-24 49" fill="none" stroke="#6d4b3b" stroke-width="11"/><path d="m84 26 9-20 12 24M111 34l20-8" fill="${c}" ${outline}/><circle cx="104" cy="43" r="5" fill="${PALETTE.inkDark}"/><path d="M98 61q10 7 20 0" fill="none" stroke="${PALETTE.inkDark}" stroke-width="3"/>`,c);
  if(id==="elephant") return objectShell(`<path d="M42 84q0-42 39-42 39 0 39 38v31H99V92q0-9-8-9v34H69V84q-8 1-8 12v15H42z" fill="${c}" ${outline}/><path d="M108 68q26 6 15 42-8 20-22 8" fill="none" ${outline}/><ellipse cx="54" cy="70" rx="22" ry="27" fill="#aeb9d5" ${outline}/>${face(82,67)}`,c);
  if(id==="giraffe") return objectShell(`<path d="M66 127V51q0-25 22-25 21 0 21 21v79H88V73H80v54z" fill="${c}" ${outline}/><path d="M72 33 66 15M99 31l7-17" ${outline}/><circle cx="66" cy="14" r="6" fill="#8c6549"/><circle cx="107" cy="13" r="6" fill="#8c6549"/><g fill="#9b6848"><circle cx="84" cy="49" r="7"/><circle cx="99" cy="79" r="8"/><circle cx="83" cy="101" r="7"/></g>${face(88,48)}`,c);
  if(id==="zebra") return objectShell(`<path d="M31 91q4-35 40-40l20-18q25-4 30 20v59H99V78l-12 9v40H64V91q-9 5-11 35H31z" fill="${c}" ${outline}/><g fill="none" stroke="${PALETTE.inkDark}" stroke-width="7"><path d="m50 61 10 20M68 53l9 24M92 46l12 17M105 69l15 10M75 91l12 11"/></g>${face(105,52)}`,c);
  if(id==="rabbit") return objectShell(`<ellipse cx="59" cy="42" rx="14" ry="31" fill="${c}" ${outline}/><ellipse cx="101" cy="42" rx="14" ry="31" fill="${c}" ${outline}/><circle cx="80" cy="88" r="43" fill="${c}" ${outline}/>${face(80,82)}<circle cx="80" cy="96" r="5" fill="${PALETTE.pink}"/>`,c);
  if(id==="fish"||id==="shark"||id==="whale"||id==="dolphin"||id==="octopus"||id==="seahorse") return seaAnimalArt(spec);
  const ear = id==="lion" ? `<circle cx="80" cy="78" r="52" fill="#c57945" ${outline}/>` : id==="panda" ? `<circle cx="50" cy="46" r="17" fill="${PALETTE.inkDark}"/><circle cx="110" cy="46" r="17" fill="${PALETTE.inkDark}"/>` : `<path d="M43 55 31 27l30 13M117 55l12-28-30 13" fill="${c}" ${outline}/>`;
  const bodyColor=id==="panda"?"#f7f5ee":c;
  const markings = id==="tiger" ? `<g stroke="${PALETTE.inkDark}" stroke-width="7"><path d="m50 49 12 17M80 41v21M110 49 98 66"/></g>` : id==="panda" ? `<ellipse cx="61" cy="75" rx="12" ry="15" fill="${PALETTE.inkDark}"/><ellipse cx="99" cy="75" rx="12" ry="15" fill="${PALETTE.inkDark}"/>` : id==="dog" ? `<ellipse cx="42" cy="55" rx="13" ry="24" fill="#8c5f48"/><ellipse cx="118" cy="55" rx="13" ry="24" fill="#8c5f48"/>` : id==="monkey"||id==="gorilla" ? `<ellipse cx="80" cy="86" rx="31" ry="28" fill="#d5a47a"/>` : "";
  return objectShell(`${ear}<circle cx="80" cy="80" r="43" fill="${bodyColor}" ${outline}/>${markings}${face(80,78)}<ellipse cx="80" cy="95" rx="8" ry="6" fill="#8a5b50"/>${highlight}`,c);
}

function seaAnimalArt(spec){const c=spec.color,id=spec.id;if(id==="octopus")return objectShell(`<circle cx="80" cy="63" r="34" fill="${c}" ${outline}/><g fill="none" ${outline}><path d="M53 83q-18 31 4 42t17-28M72 94q-4 36 14 35t4-35M93 91q12 35 27 24t-7-31"/></g>${face(80,60)}`,c);if(id==="seahorse")return objectShell(`<path d="M93 31q-35-11-39 20-3 23 23 27v25q0 25 23 25 21 0 19-21-2-16-21-11V70q25-11 16-30-6-13-21-9z" fill="${c}" ${outline}/><path d="m57 55-18 8 19 8" fill="#f2c84b" ${outline}/><circle cx="91" cy="47" r="4" fill="${PALETTE.inkDark}"/>`,c);if(id==="whale")return objectShell(`<path d="M25 88q8-52 66-52 46 0 54 38-7 49-66 52-48 2-54-38z" fill="${c}" ${outline}/><path d="M31 80 8 58q-5 31 22 43M80 40Q75 8 56 15M82 40q8-32 29-22" fill="${c}" ${outline}/><circle cx="113" cy="67" r="5"/><path d="M119 88q10 7 19-2" fill="none" stroke="${PALETTE.ink}" stroke-width="4"/>`,c);if(id==="dolphin")return objectShell(`<path d="M21 94q34-72 100-48l25-20-4 35 14 27-38-7q-36 47-97 13z" fill="${c}" ${outline}/><path d="M79 56 61 24q31 5 38 28M77 99l-7 31q27-8 35-36" fill="${c}" ${outline}/><circle cx="112" cy="55" r="5"/>`,c);const tail=id==="shark"?`<path d="m112 78 35-28-8 30 8 29-35-25z" fill="${c}" ${outline}/>`:`<path d="m111 79 34-22v44z" fill="${c}" ${outline}/>`;const fin=id==="shark"?`<path d="m77 50 15-31 10 39" fill="${c}" ${outline}/>`:"";return objectShell(`${tail}<ellipse cx="77" cy="80" rx="51" ry="32" fill="${c}" ${outline}/>${fin}<circle cx="54" cy="72" r="4" fill="${PALETTE.inkDark}"/><path d="M47 90q11 8 22 0" fill="none" stroke="${PALETTE.inkDark}" stroke-width="3.5" stroke-linecap="round"/>`,c)}

