function objectSvg(spec){if(spec.kind==="animal")return animalArt(spec);if(spec.kind==="seaAnimal")return seaAnimalArt(spec);if(spec.kind==="fruit")return fruitArt(spec);if(spec.kind==="vegetable")return vegetableArt(spec);if(spec.kind==="toy")return toyArt(spec);if(spec.kind==="clothing")return clothingArt(spec);if(spec.kind==="school")return schoolArt(spec);if(spec.kind==="home")return homeArt(spec);if(["landVehicle","seaVehicle","airVehicle"].includes(spec.kind))return vehicleArt(spec);if(spec.kind==="nature")return natureArt(spec);return foodArt(spec)}

function sceneShell(title, body, sky="#bdeaf4", ground="#72bd73"){
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 600 600" role="img" aria-labelledby="title"><title id="title">${esc(title)}</title><defs><linearGradient id="sky" x1="0" y1="0" x2="0" y2="1"><stop stop-color="${sky}"/><stop offset="1" stop-color="#f8f1cb"/></linearGradient><filter id="shadow" x="-20%" y="-20%" width="140%" height="150%"><feDropShadow dx="0" dy="7" stdDeviation="6" flood-color="#30285a" flood-opacity=".18"/></filter></defs><rect width="600" height="600" rx="28" fill="url(#sky)"/><circle cx="95" cy="92" r="43" fill="#ffd765"/><path d="M0 370Q130 300 260 365T600 340V600H0z" fill="${ground}"/><path d="M0 445q140-70 290 4t310-9v160H0z" fill="#4f9d65" opacity=".5"/>${body}</svg>`;
}

