const flower=(x,y,c="#ef8fb8")=>`<g transform="translate(${x} ${y})"><path d="M0 10v42" stroke="#3f8654" stroke-width="7"/><g fill="${c}" stroke="#493a85" stroke-width="3"><circle cx="0" cy="0" r="12"/><circle cx="-13" cy="9" r="11"/><circle cx="13" cy="9" r="11"/><circle cx="-8" cy="-10" r="11"/><circle cx="8" cy="-10" r="11"/></g><circle cx="0" cy="1" r="7" fill="#ffd765"/></g>`;
